from pathlib import Path
P=Path(__file__).parent;E=P/'meridian-deck/elements'
def add(e,s):
 f=E/e/'element.css';f.write_text(f.read_text()+'\n/* Final geometry review fixes. */\n'+s.replace('@',f'[data-el="meridian-deck-{e}"]'))
add('prose','@.prose{flex:1 1 0;height:auto}')
add('pill','@.pill{min-height:calc(var(--type-20)*var(--name-line) + var(--gap-sm)*2)}')
add('chart-bar','@.h{padding-left:calc(var(--gap-lg)*5)}@.h .bar>span{width:calc(var(--gap-lg)*4);max-width:calc(var(--gap-lg)*4);white-space:normal;text-align:right;font-size:var(--type-14);line-height:var(--label-line)}')
add('card','@.card.on:not(:has(.mark,.fig,.kick)){width:268px;height:268px;max-width:100%;max-height:100%;flex:none;align-self:center;margin:auto;border-radius:999px;border:0;padding:var(--pad)}@.card.on:not(:has(.mark,.fig,.kick)) .parts{display:flex;height:auto;gap:var(--gap-sm)}@.card.on:not(:has(.mark,.fig,.kick)) .name{font-size:var(--type-28);min-height:0;border:0;padding:0}@.card.on:not(:has(.mark,.fig,.kick)) .note{font-size:var(--type-16)}')
add('hub','@ .core{width:min(35cqw,70cqh);height:min(35cqw,70cqh)}@:has(>.spoke:nth-child(4 of .spoke):last-child)::before{content:none}@:has(>.spoke:nth-child(4 of .spoke):last-child)>.spoke{width:min(15cqw,29cqh);height:min(15cqw,29cqh)}@:has(>.spoke:nth-child(4 of .spoke):last-child)>.spoke:nth-child(1 of .spoke){left:34%;top:26%}@:has(>.spoke:nth-child(4 of .spoke):last-child)>.spoke:nth-child(2 of .spoke){left:66%;top:26%}@:has(>.spoke:nth-child(4 of .spoke):last-child)>.spoke:nth-child(3 of .spoke){left:34%;top:74%}@:has(>.spoke:nth-child(4 of .spoke):last-child)>.spoke:nth-child(4 of .spoke){left:66%;top:74%}@:has(>.spoke:nth-child(4 of .spoke):last-child)>.spoke .note{position:absolute;width:25cqw;top:50%;translate:0 -50%;color:var(--n-7);font-size:var(--type-16);line-height:var(--body-line);text-align:center;border-top:var(--stroke) solid var(--n-4);border-bottom:var(--stroke) solid var(--n-4);padding:var(--gap-sm) 0}@:has(>.spoke:nth-child(4 of .spoke):last-child)>.spoke:nth-child(odd of .spoke) .note{right:calc(100% + var(--gap-sm))}@:has(>.spoke:nth-child(4 of .spoke):last-child)>.spoke:nth-child(even of .spoke) .note{left:calc(100% + var(--gap-sm))}')
add('cycle','@::after{content:"";position:absolute;left:73%;top:22%;width:14px;height:14px;background:var(--a1);clip-path:polygon(0 0,100% 50%,0 100%);rotate:40deg}')
print('Clipping and source geometry corrections applied')
